  demo: '<div class="space-ruler">\n    <span class="space-block" style="width:8px"></span><span class="space-num">小</span>\n    <span class="space-block" style="width:16px"></span><span class="space-num">中</span>\n    <span class="space-block" style="width:24px"></span><span class="space-num">大</span>\n  </div>',
