    demo: '<div class="space-ruler">\n    <span class="space-block" style="width:8px"></span><span class="space-num">Small</span>\n    <span class="space-block" style="width:16px"></span><span class="space-num">medium</span>\n    <span class="space-block" style="width:24px"></span><span class="space-num">Large</span>\n  </div>'
