  demo: '<div class="chk-col">\n        <label class="demo-check"><input type="checkbox" checked><i></i>前端</label>\n        <label class="demo-check"><input type="checkbox" checked><i></i>后端</label>\n        <label class="demo-check"><input type="checkbox"><i></i>设计</label>\n      </div>',
