  id: "segmented",
  name: "Segmented",
  cn: "分段控件",
  cat: "内容展示",
  tagline: "把少量选项并排放在一起，点一下就切换当前查看方式",
  desc: "例如在任务页点击“列表 / 看板 / 日历”，同一批任务会换一种展示方式。它不负责前往另一个页面；选项很多时也不适合全部塞进这里。",
