  demo: '<div class="cpl-live"><div class="cpl-item"><input type="checkbox" id="cpl1" checked><label class="cpl-head" for="cpl1">如何邀请团队成员？<span class="cpl-arrow">▸</span></label><div class="cpl-body"><span class="cpl-in">进入「项目设置 → 成员」，点击“邀请成员”，输入对方邮箱即可。</span></div></div><div class="cpl-item"><input type="checkbox" id="cpl2"><label class="cpl-head" for="cpl2">支持导出数据吗？<span class="cpl-arrow">▸</span></label><div class="cpl-body"><span class="cpl-in">支持，项目设置里可导出 CSV 或 JSON。</span></div></div></div>',
