    demo: '<div class="footer-demo">\n    <div class="footer-d-main">\n      <span class="footer-d-brand"><b>◆ VibeUI</b><i>Turn ideas into web pages</i></span>\n      <span class="footer-col"><b>Products</b><a>Features</a><a>Pricing</a><a>Change Log</a></span>\n      <span class="footer-col"><b>Resources</b><a>Documentation</a><a>Blog</a><a>Templates</a></span>\n      <span class="footer-col"><b>Company</b><a>About</a><a>Join Us</a><a>Contact</a></span>\n    </div>\n    <div class="footer-base"><span>\xa9 2026 VibeUI \xb7 Filing information (if applicable)</span><span class="footer-social"><i>✉</i><i>X</i><i>▶</i></span></div>\n  </div>'
