  demo: '<div class="pricing-demo pricing-demo-col"><small class="pricing-demo-note">虚构示例 \xb7 价格、权益与推荐标签均为演示数据</small>\n    <div class="pricing-d-row">\n      <div class="pricing-card">\n        <b class="pricing-tier">免费版</b><span class="pricing-price">\xa50<small>/月</small></span>\n        <span class="pricing-feats"><i>✓ 10 个项目</i><i>✓ 100 次生成 / 月</i><i>✓ 社区支持</i></span>\n        <span class="pricing-btn ghost">开始使用</span>\n      </div>\n      <div class="pricing-card hot">\n        <span class="pricing-badge">适合高频使用者</span>\n        <b class="pricing-tier">专业版</b><span class="pricing-price">\xa549<small>/月</small></span>\n        <span class="pricing-feats"><i>✓ 不限项目</i><i>✓ 自定义域名</i><i>✓ 优先支持</i></span>\n        <span class="pricing-btn">升级专业版</span>\n      </div>\n      <div class="pricing-card">\n        <b class="pricing-tier">团队版</b><span class="pricing-price">\xa5199<small>/月</small></span>\n        <span class="pricing-feats"><i>✓ 多人协作</i><i>✓ 权限管理</i><i>✓ 专属客服</i></span>\n        <span class="pricing-btn ghost">联系销售</span>\n      </div>\n    </div>\n  </div>',
