  demo: '<div class="serif-demo">\n    <div class="serif-col serif-serif-f"><b>好的设计经得起凝视</b><p>同一段文案，衬线让它显得优雅、正式，像杂志里的编辑精选。</p><span class="serif-tag">衬线 \xb7 Georgia / 宋体</span></div>\n    <div class="serif-col"><b>好的设计经得起凝视</b><p>同一段文案，非衬线让它显得现代、干净，像效率工具的界面。</p><span class="serif-tag">非衬线 \xb7 系统默认</span></div>\n  </div>',
