    demo: '<div class="hover-play">\n    <span class="hover-live-card"><b>Hover me</b><i>Lift + color</i></span>\n    <span class="hover-dead-card"><b>Control</b><i>I don\'t react</i></span>\n    <span class="hover-hint">Move your mouse over them ↑</span>\n  </div>'
