  demo: '<div class="api-demo">\n    <div class="api-req"><span class="api-tag">请求 REQUEST</span><br><span class="api-method">GET</span> https://api.vibeui.dev/weather?city=shenzhen<br><span style="color:var(--text-3)">Authorization: Bearer <span class="api-key-token">sk-••••3f2k</span></span></div>\n    <div class="api-arrow">↓</div>\n    <div class="api-resp"><span class="api-tag">响应 RESPONSE</span><br><span class="api-status-ok">200 OK</span><br>{ "city": "深圳", "temp": 31, "text": "多云" }</div>\n  </div>',
