  demo: '<div class="http-demo">\n    <div class="http-msg"><span class="http-title">GET —— 获取资源</span><br><span class="http-method-get">GET</span> <span class="http-url">/api/components HTTP/1.1</span><br><span class="http-head">Host: api.vibeui.dev</span></div>\n    <div class="http-msg"><span class="http-title">POST —— 交数据</span><br><span class="http-method-post">POST</span> <span class="http-url">/api/login HTTP/1.1</span><br><span class="http-head">Content-Type: application/json</span><span class="http-body">{ "email": "you@example.com", "pwd": "••••••" }</span></div>\n  </div>',
