  demo: '<div class="json-demo"><pre>{\n  <span class="json-k">"name"</span><span class="json-p">:</span> <span class="json-s">"按钮 Button"</span><span class="json-p">,</span>\n  <span class="json-k">"price"</span><span class="json-p">:</span> <span class="json-n">0</span><span class="json-p">,</span>\n  <span class="json-k">"free"</span><span class="json-p">:</span> <span class="json-b">true</span><span class="json-p">,</span>\n  <span class="json-k">"tags"</span><span class="json-p">:</span> <span class="json-p">[</span><span class="json-s">"通用"</span><span class="json-p">,</span> <span class="json-s">"表单"</span><span class="json-p">]</span>\n}</pre></div>',
