    desc: "At 1440px, a site may show three card columns and full navigation; at 390px, it can use one column, larger touch targets, and collapsed secondary navigation. Breakpoints and media queries are common tools. The goal is not proportional desktop shrinkage but readable, tappable, completable tasks.",
    demo: '\n  <div class="foundation-card-visual fc-responsive">\n    <div class="fc-responsive-view desktop"><small>1440px</small><header>VibeHub　Learn　Search　About</header><section><i></i><i></i><i></i></section></div>\n    <b>→ reflow →</b>\n    <div class="fc-responsive-view mobile"><small>390px</small><header>VibeHub　☰</header><section><i></i><i></i><i></i></section></div>\n    <div class="fc-foot">Same content \xb7 three columns become one \xb7 task stays usable</div>\n  </div>'
