  quote: "手机宽度下把三列改成一列，桌面的导航和卡片布局保持不变。",
  aliases: ["响应式", "自适应布局", "CSS Media Query", "媒体查询", "响应式网页设计", "自适应设计", "Responsive Web Design", "断点", "Breakpoint", "像素断点"],
  prerequisites: ["flex", "grid"],
