  cat: "内容展示",
  tagline: "筛选是按已有属性或条件缩小当前内容集合的功能。",
  desc: "例如任务列表可按负责人、状态和截止日期只保留符合条件的项，商品列表可按价格或尺寸缩小范围。它基于明确条件排除不符合的内容，不负责理解用户自由输入的一句话，也不等于给结果排序。",
  demo: '\n  <div class="foundation-card-visual fc-filter">\n    <div class="fc-filter-controls"><span>状态：待处理 \xd7</span><span>期限：本周 \xd7</span><button>重置</button></div>\n    <div class="fc-filter-list"><article><b>修复登录错误</b><small>待处理 \xb7 本周</small></article><article><b>检查手机布局</b><small>待处理 \xb7 本周</small></article><i>5 条 → 2 条</i></div>\n    <div class="fc-foot">条件来自任务已有字段</div>\n  </div>',
