  demo: '<div class="npm-demo">\n    <div class="npm-card">\n      <span class="npm-tag">package.json \xb7 清单</span>\n      <span><b class="npm-k">"react"</b>: "^19.0.0"</span>\n      <span><b class="npm-k">"vite"</b>: "^6.0.0"</span>\n      <span><b class="npm-k">"scripts"</b>: dev / build</span>\n    </div>\n    <span class="npm-arrow">npm<br>install<br>→</span>\n    <div class="npm-card">\n      <span class="npm-tag">node_modules \xb7 依赖目录</span>\n      <span>\uD83D\uDCE6 react</span>\n      <span>\uD83D\uDCE6 vite</span>\n      <span>\uD83D\uDCE6 …共 42 个包</span>\n    </div>\n  </div>',
