  id: "env-var",
  name: "Env Var",
  cn: "环境变量",
  cat: "上线与排错",
  tagline: "环境变量是在代码外保存设置值、让不同运行地点读取各自配置的方式。",
  desc: "例如本机测试、测试地址和正式网站可以分别使用不同服务地址或密钥。会发到浏览器的设置谁都能查看，真正的密钥只能留在服务器。`.env` 常用来在本机保存这些值，但它不是保险箱，也不应上传到代码仓库。",
  demo: '<div class="env-var-demo">\n    <div class="env-var-file">\n      <span class="env-var-tag">.env \xb7 本地开发配置</span>\n      <span><b class="env-var-key">OPENAI_API_KEY</b>=<i>sk-proj-••••••</i></span>\n      <span><b class="env-var-key">DATABASE_URL</b>=<i>postgres://••••</i></span>\n    </div>\n    <div class="env-var-row">\n      <span class="env-var-code">process.env.OPENAI_API_KEY</span>\n      <span class="env-var-shield">\uD83D\uDEE1 .gitignore 规则已匹配；提交前再看 git status</span>\n    </div>\n  </div>',
  en: {
    quote: "I know a secret key shouldn't go in the code. Where should I put it?",
    tagline: "Provide configuration outside the source code",
    desc: "Environment variables supply values such as API endpoints, feature settings, and secret keys when a program starts. Public browser variables are visible to visitors, even if their names come from an environment file. Keep real secrets on the server and document the required variable names with safe examples.",
    demo: '<div class="env-var-demo">\n    <div class="env-var-file">\n      <span class="env-var-tag">.env \xb7 Local development configuration</span>\n      <span><b class="env-var-key">OPENAI_API_KEY</b>=<i>sk-proj-••••••</i></span>\n      <span><b class="env-var-key">DATABASE_URL</b>=<i>postgres://••••</i></span>\n    </div>\n    <div class="env-var-row">\n      <span class="env-var-code">process.env.OPENAI_API_KEY</span>\n      <span class="env-var-shield">\uD83D\uDEE1 .gitignore rule has been matched; check git status before submitting</span>\n    </div>\n  </div>'
  },
  quote: "密钥不能直接写进代码里，那应该放哪？",
  prerequisites: ["terminal"]
