  desc: "例如平台取得项目文件后，生成可运行的网页或启动服务，再放到测试地址、内部地址或公开网址。发布前要确认发往哪里、怎样启动和需要哪些设置；失败时先查看系统记录的报错。",
  demo: '<div class="deploy-demo">\n    <span class="deploy-step">本地文件</span>\n    <i class="deploy-arrow">→</i>\n    <span class="deploy-step">build 打包</span>\n    <i class="deploy-arrow">→</i>\n    <span class="deploy-step">托管平台</span>\n    <i class="deploy-arrow">→</i>\n    <span class="deploy-step deploy-on">my-app.vercel.app</span>\n  </div><span style="font-size:12px;color:var(--text-3)">这是公开静态前端的示例；服务部署还需要运行与访问配置</span>',
  en: {
    quote: "I finished the site. How do I make it available at a URL that other people can open?",
    tagline: "Build the project and make it available on a server",
    desc: "Deployment turns source code into a running website or service. It may install dependencies, build assets, set environment variables, start processes, and connect a domain. A repeatable deployment includes logs, health checks, and a way to return to a known working version.",
    demo: '<div class="deploy-demo">\n    <span class="deploy-step">Local files</span>\n    <i class="deploy-arrow">→</i>\n    <span class="deploy-step">build package</span>\n    <i class="deploy-arrow">→</i>\n    <span class="deploy-step">Hosting platform</span>\n    <i class="deploy-arrow">→</i>\n    <span class="deploy-step deploy-on">my-app.vercel.app</span>\n  </div><span style="font-size:12px;color:var(--text-3)">This is an example of exposing a static front end; service deployment also requires running and access configuration</span>'
  },
  quote: "我做好了，怎么才能让别人用一个网址就能打开我的页面？",
  prerequisites: ["terminal", "npm", "env-var", "domain"]
