    tagline: "A unit test tests one independently verifiable function, component, or small module.",
    desc: "Pass a fixed price to a tax function and assert the amount, or check that a disabled button does not submit. It isolates outside services so a failure points to a small responsibility. A full login with browser, API, and real database is not a unit test.",
    demo: '<div class="testing-delivery-preview tdv-unit-test"><div class="tdv-code"><code>calculateTotal(100, .08)</code><span>expect(result).toBe(108)</span><b>✓ 1 passed</b><small>payment / database off</small></div></div>'
