  cn: "端到端测试",
  cat: "测试",
  tagline: "模拟真实用户跨页面跨系统完整操作流的端到端集成测试。",
  desc: "例如在浏览器里选择旅行日期、填写乘客、完成测试付款，再确认订单页出现正确行程。它检查用户从开始操作到看到结果的整条路径，但不表示每一种内部情况都已检查。",
  demo: '<div class="testing-delivery-preview tdv-e2e-test"><div class="tdv-browser"><header>trip.local/confirmation</header><ol><li>✓ 选行程</li><li>✓ 付款</li><li>✓ 确认</li></ol><strong>BK-2048</strong></div></div>',
