  tagline: "持续交付和持续部署，是把检查通过的版本继续送往可访问地址的两种做法。",
  desc: "持续交付会把版本准备好，仍由人决定何时正式发布；持续部署会在检查通过后自动正式发布。两者的差别是，正式发布前是否保留人工确认。",
