    tagline: "Save one meaningful set of changes in the project history",
    desc: "A commit records selected changes with an author, time, and message. Before undoing work, distinguish uncommitted edits from commits that have already been pushed. Shared history is usually reversed with a new revert commit instead of rewriting old records.",
    demo: '<div class="git-story git-story--commit is-card">\n  <div class="git-story-main"><div class="git-simple-flow git-simple-flow--commit">\n      <div class="git-file-card is-change"><span class="git-file-mark"></span><span><b>Current changes</b><small>This is still the current change</small></span></div>\n      <div class="git-motion"><span>Save as a version</span><small>commit</small><i>→</i></div>\n      <div class="git-version-card is-new"><span class="git-version-check">✓</span><span><b>Saved version</b><small>Just saved on this computer</small></span><span class="git-version-dots"><i></i><i></i><i class="is-current"></i></span></div>\n    </div></div>\n  \n</div>'
