  tagline: "把当前没做完的改动临时收起来，让工作区先恢复干净",
  desc: "例如，首页改到一半却要切去修 Bug，可以先 Stash，处理完再恢复。刚新建且从未加入 Git 的文件默认不会被收起，操作前要看 git status；Stash 只适合短期中转，正式成果仍要{c:commit}。",
  demo: '<div class="git-story git-story--stash is-card">\n  <div class="git-story-main"><div class="git-stash-visual">\n      <div class="git-file-card is-change"><span class="git-file-mark"></span><span><b>表单还没改完</b><small>暂时不能保存成版本</small></span></div>\n      <div class="git-motion"><span>临时收起</span><small>stash</small><i>→</i></div>\n      <div class="git-drawer"><span class="git-drawer-handle"></span><b>未完成改动</b><small>需要时再放回</small></div>\n      <div class="git-clean-state"><i>✓</i><span><b>工作区已清爽</b><small>可以先切换任务</small></span></div>\n    </div></div>\n  \n</div>',
  en: {
    quote: "I'm in the middle of changes but need to switch to something else. Can I put this work aside for now?",
    tagline: "Temporarily set aside uncommitted changes",
    desc: "Stash stores selected working changes and restores a cleaner directory so another task can proceed. It is useful for short interruptions, not as a long-term archive. Name important stashes and inspect conflicts when applying them later.",
    demo: '<div class="git-story git-story--stash is-card">\n  <div class="git-story-main"><div class="git-stash-visual">\n      <div class="git-file-card is-change"><span class="git-file-mark"></span><span><b>The form has not been changed yet</b><small>Cannot be saved as a version yet</small></span></div>\n      <div class="git-motion"><span>Temporarily collapse</span><small>stash</small><i>→</i></div>\n      <div class="git-drawer"><span class="git-drawer-handle"></span><b>Unfinished changes</b><small>Replace if needed</small></div>\n      <div class="git-clean-state"><i>✓</i><span><b>The workspace is clean</b><small>You can switch tasks first</small></span></div>\n    </div></div>\n  \n</div>'
  },
  quote: "改到一半要切去干别的，先把现在这些东西临时收起来。",
  prerequisites: ["git", "branch"]
