  id: "gitignore",
  name: ".gitignore",
  cn: "忽略文件",
  cat: "Git",
  tagline: "告诉 Git 哪些本地文件不要加入版本记录的规则清单",
  desc: "例如可重新下载的工具文件和本机保存的密钥文件，通常会写进忽略规则。它只对还没被版本记录保存的文件生效；已经保存过的文件不会因此消失，已经泄露的密钥也必须立即更换。",
  demo: '<div class="git-story git-story--gitignore is-card">\n  <div class="git-story-main"><div class="git-ignore-visual">\n      <div class="git-file-list"><span><i></i>index.html <b>会记录</b></span><span><i></i>style.css <b>会记录</b></span><span class="is-secret"><i></i>.env <b>不记录</b></span></div>\n      <div class="git-ignore-rule"><span class="git-shield">\xd7</span><span><b>.gitignore</b><small>把本地密钥挡在版本历史外</small></span></div>\n    </div></div>\n  \n</div>',
  en: {
    quote: "There are files I don't want Git to track, like secret keys and dependency packages. How do I exclude them?",
    tagline: "Tell Git which untracked files should stay out of version control",
    desc: ".gitignore patterns keep generated files, dependencies, local settings, and secrets from being added by accident. It does not remove files that are already tracked, and it should not replace secure secret management.",
    demo: '<div class="git-story git-story--gitignore is-card">\n  <div class="git-story-main"><div class="git-ignore-visual">\n      <div class="git-file-list"><span><i></i>index.html <b>Tracked</b></span><span><i></i>style.css <b>Tracked</b></span><span class="is-secret"><i></i>.env <b>Ignored</b></span></div>\n      <div class="git-ignore-rule"><span class="git-shield">\xd7</span><span><b>.gitignore</b><small>Keep local secrets out of version control</small></span></div>\n    </div></div>\n  \n</div>'
  },
  quote: "有些文件我不想让 Git 管，比如密钥和依赖包，怎么排除掉？",
