  id: "route",
  name: "Route & Endpoint",
  cn: "路由与端点",
  cat: "后端开发",
  tagline: "路由决定访问一个网址或执行一种操作时，应交给后端的哪段功能处理。",
  desc: "例如打开文章列表和提交一篇新文章，会交给两段不同功能处理。每个对外入口都要写清需要提供什么、成功后返回什么、失败时怎样说明。",
  demo: '<div class="route-demo">\n    <div class="route-board">\n      <div class="route-row on"><b class="m-get">GET</b><code>/api/posts</code><span>→ 列表处理</span></div>\n      <div class="route-row"><b class="m-post">POST</b><code>/api/posts</code><span>→ 创建处理</span></div>\n      <div class="route-row"><b class="m-get">GET</b><code>/api/posts/:id</code><span>→ 详情处理</span></div>\n    </div>\n    <span class="route-note">方法和路径一起决定进哪段代码</span>\n  </div>',
  en: {
    quote: "When people visit different URLs, how do I send each one to the right code?",
    tagline: "Match a request path and method to the code that handles it",
    desc: "A backend route, or endpoint, defines where a request goes and which methods it accepts. For example, GET /products may read products while POST /products creates one. Validate input, check access, return meaningful status codes, and keep unrelated operations separate.",
    demo: '<div class="route-demo">\n    <div class="route-board">\n      <div class="route-row on"><b class="m-get">GET</b><code>/api/posts</code><span>→ List processing</span></div>\n      <div class="route-row"><b class="m-post">POST</b><code>/api/posts</code><span>→ Create processing</span></div>\n      <div class="route-row"><b class="m-get">GET</b><code>/api/posts/:id</code><span>→ Details processing</span></div>\n    </div>\n    <span class="route-note">Method and path together determine which code to enter</span>\n  </div>'
  },
  quote: "用户访问不同的网址，怎么让不同的代码来接管？",
  aliases: ["路由", "Endpoint", "API Endpoint", "接口端点"],
  prerequisites: ["backend", "http", "api"]
