  desc: "例如，旅行者需要保存未完成的行程，以便换一台设备后继续编辑。用户故事为需求讨论提供起点，但不会替代交互细节、验收标准或技术方案。",
  demo: '<div class="product-mini story-mini"><small>用户故事</small><b>旅行者需要保存未完成的行程</b><span>以便稍后继续编辑</span></div>',
