  name: "System Prompt",
  cn: "系统提示词",
  cat: "上下文",
  tagline: "系统提示词是 AI 产品在背后先交给模型的规则，例如客服助手该用什么语气、哪些问题不能自行处理。",
  desc: "例如客服助手收到“退款超过 500 元要转人工”这条规则后，会在遇到大额退款时提示转接。它只能影响模型的回答，真正拦住退款仍要靠产品的权限检查。",
  demo: '\n  <div class="ai-card-visual ai-card-system-prompt">\n    <div class="aic-system-rule"><small>系统规则</small><b>删除前必须确认</b></div>\n    <div class="aic-system-stack"><span><small>用户</small><b>现在就删</b></span><i>＋</i><span class="model"><small>模型</small><b>先请求确认</b></span><i>→</i><span class="gate"><small>产品权限</small><b>未确认 \xb7 拦截</b></span></div>\n    <div class="aic-foot">提示词影响建议 \xb7 产品代码执行权限</div>\n  </div>',
