  tagline: "流式响应是 AI 一边生成内容，界面一边逐段显示内容的方式。",
  desc: "例如，聊天回答会像打字一样逐段出现。首段更早可见不代表整份回答更早完成，总时长仍受后续生成和传输影响。",
  demo: '\n  <div class="ai-card-visual ai-card-streaming">\n    <div class="aic-stream-events"><small>响应事件</small><span>“这个”</span><span>“按钮”</span><span>“可以…”</span><i>•••</i></div>\n    <div class="aic-stream-bubble"><small>界面持续追加</small><b>这个按钮可以<span class="cursor"></span></b></div>\n    <div class="aic-foot">首段已可见 \xb7 完整回答仍在生成</div>\n  </div>',
