  demo: '<div class="style-minimal-demo minimal-thumb"><small>ROUTINE / TODAY</small><h2>Ship the onboarding flow</h2><p>One clear priority. Nothing competing for attention.</p><div><span>09:30 — 11:00</span><button>Start focus <i class="ti ti-arrow-up-right"></i></button></div><footer><i class="ti ti-check"></i> 3 of 5 tasks complete</footer></div>',
