  demo: '<div class="style-y2k-demo style-y2k-profile"><i class="style-y2k-star" style="top:12px;left:8%;font-size:15px">✦</i><i class="style-y2k-star" style="bottom:12px;right:8%;font-size:14px">✧</i><div class="y2k-browser"><b>myspace.exe</b><span>home \xb7 diary \xb7 mix</span><i>ONLINE ♡</i></div><div class="y2k-main"><section class="y2k-person"><div class="y2k-avatar">LU</div><b>lulu_2000</b><span>shanghai \xb7 7,872 friends</span><button>+ add friend</button></section><section class="y2k-player"><small>NOW PLAYING</small><b>plastic hearts</b><span>〈 THE SATURDAYS 〉</span><div class="y2k-progress"><i></i></div><div class="y2k-controls">◀　 <strong>▶</strong>　 ▶</div></section><aside class="y2k-guest"><b>GUESTBOOK</b><span>momo: ur playlist is ☆</span><span>nana: call me later!</span><em>sign my book →</em></aside></div></div>',
