    tagline: "A placeholder is the gray example inside an input box showing the expected format; it vanishes the moment you type.",
    desc: 'The gray you@example.com in an email box demonstrates "fill it like this" and steps aside at the first keystroke. It splits the job with the label: the label sits beside the box and stays, while the placeholder only opens the show—once typing starts, only the label tells you what the field is.',
    demo: '<div class="wf-card wf-ph-card"><span class="lbl">Email</span><b class="ph">you@example.com</b><i>vanishes on typing</i><b>label stays \xb7 placeholder opens</b></div>'
