  desc: "「高级一点」「有呼吸感」这类形容词，你和 AI 的理解经常对不上。先收集三五张你喜欢的网站截图、一两张不喜欢的，加上想要的主色，拼成一张图发给 AI——它照着做，比靠形容词描述准得多。选错方向的成本在拼图阶段最低：换一张参考图就行，做完再改要动的地方多得多。",
