    desc: 'You test with a mouse and good eyes, but visitors may use a keyboard, a screen reader, or squint at a phone in sunlight. Accessibility extends "works for me" to those situations: text alternatives on images, buttons reachable by Tab, sufficient text contrast. When an AI reply mentions a11y, it is the shorthand for this word (a plus 11 letters plus y).',
    demo: '<div class="wf-card wf-a11y-card"><span class="chk"><i class="dot"></i>Images have alt text</span><span class="chk"><i class="dot"></i>Buttons reachable by Tab</span><span class="chk"><i class="dot"></i>Contrast sufficient</span><b>swap the mouse and good eyes—still usable?</b></div>'
