  demo: '<div class="ai-card-visual ai-card-provider"><div><small>Provider</small><b>OpenRouter</b></div><i>→</i><div><small>Model</small><b>deepseek-v4-flash</b></div><footer>通过服务平台调用具体模型</footer></div>',
