    demo: '<div class="ai-card-visual ai-card-base-url"><code>https://openrouter.ai/api/v1</code><strong>+</strong><code>/chat/completions</code><strong>=</strong><code>https://openrouter.ai/api/v1/chat/completions</code><footer>base address + request path</footer></div>'
