    desc: "For example, an AI tool can send a request to a relay, which forwards it to a model provider and returns the result along the same path. The relay may handle authentication, routing, or a shared gateway, but that does not mean the model runs there. Prompts, file fragments, and credentials may pass through it, so verify the operator, privacy policy, retention rules, and key issuer before use.",
    demo: '<div class="ai-card-visual ai-card-api-proxy"><span>You</span><i>↔</i><span>proxy relay</span><i>↔</i><span>model provider</span><footer>request out, result back along the same path</footer></div>'
