  desc: "例如给网页接上 AI 能力：程序从环境变量读取 API Key，并随请求交给服务验证。服务通常把权限和用量记到 Key 所属的账户、项目或应用，而不一定代表某个具体的人。Key 一旦泄露，别人可能消耗额度或访问数据；不要把它写进代码、仓库或聊天记录，发现泄露后立即吊销并更换。",
