  desc: "例如 AI 工具可以让命令只在当前工作区内读写，并限制网络访问，从而减少错误脚本影响其他文件的机会。沙箱可以由操作系统机制、容器或虚拟机实现，隔离强度取决于实际边界；已挂载的敏感目录、注入的真实密钥和允许的网络仍可能被代码使用。",
  demo: '<div class="ai-card-visual ai-card-sandbox"><span>host files</span><i>\xd7</i><b>sandbox boundary</b><i>\xd7</i><span>untrusted code</span><footer>limited filesystem and process access</footer></div>',
