  demo: '<div style="max-width:520px;margin:0 auto;font-size:14px"><div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap"><div style="border:1px solid var(--border);border-radius:8px;padding:12px;background:var(--bg);flex:1;min-width:150px"><b>orders</b><div style="margin-top:8px;color:var(--text-2)">order_42 \xb7 待提交</div></div><span style="font-size:20px;color:var(--brand)">＋</span><div style="border:1px solid var(--border);border-radius:8px;padding:12px;background:var(--bg);flex:1;min-width:150px"><b>inventory</b><div style="margin-top:8px;color:var(--text-2)">item_7 \xb7 还剩 0 件</div></div></div><div style="text-align:center;margin:12px 0;color:var(--text-2)">库存不足 → <span style="color:var(--red);font-weight:600">ROLLBACK：两边都不保存</span></div></div>',
  en: {
    quote: "Creating an order and deducting stock must succeed together; if any step fails, it must not leave half an order behind.",
    tagline: "A group of related database operations that are committed or rolled back as a whole",
    desc: "When an order is created, the system usually writes the order record and deducts inventory together. If stock is unavailable, the order should not remain. A transaction rolls back this group of operations in the same database, but it does not automatically undo external actions like payments or emails.",
    demo: '<div style="max-width:520px;margin:0 auto;font-size:14px"><div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap"><div style="border:1px solid var(--border);border-radius:8px;padding:12px;background:var(--bg);flex:1;min-width:150px"><b>orders</b><div style="margin-top:8px;color:var(--text-2)">order_42 \xb7 pending</div></div><span style="font-size:20px;color:var(--brand)">+</span><div style="border:1px solid var(--border);border-radius:8px;padding:12px;background:var(--bg);flex:1;min-width:150px"><b>inventory</b><div style="margin-top:8px;color:var(--text-2)">item_7 \xb7 0 left</div></div></div><div style="text-align:center;margin:12px 0;color:var(--text-2)">Out of stock → <span style="color:var(--red);font-weight:600">ROLLBACK: save neither change</span></div></div>'
  },
  quote: "创建订单和扣库存必须一起成功，任何一步失败都不能留下半个订单。",
