  demo: '<div style="max-width:540px;margin:0 auto;font-size:14px"><div style="display:flex;gap:10px;align-items:stretch;flex-wrap:wrap"><div style="border:1px solid var(--border);border-radius:8px;padding:12px;background:var(--bg);flex:1;min-width:190px"><b>请求 A</b><div style="margin-top:8px;color:var(--text-2)">订单 ✓　库存 1 → 0</div></div><div style="border:1px solid var(--border);border-radius:8px;padding:12px;background:var(--bg);flex:1;min-width:190px"><b>请求 B</b><div style="margin-top:8px;color:var(--text-2)">订单 ✕　库存仍为 0</div></div></div><div style="text-align:center;margin-top:12px;color:var(--brand);font-weight:600">最终：获胜请求的多步操作完整生效，失败请求整体回滚撤销</div></div>',
