    desc: "When two people buy the last item at the same time, checking and deducting inventory must be an indivisible whole so one succeeds and the other fails. Atomicity covers only the defined operation scope; it does not make every distributed step across systems roll back together.",
    demo: '<div style="max-width:540px;margin:0 auto;font-size:14px"><div style="display:flex;gap:10px;align-items:stretch;flex-wrap:wrap"><div style="border:1px solid var(--border);border-radius:8px;padding:12px;background:var(--bg);flex:1;min-width:190px"><b>Request A</b><div style="margin-top:8px;color:var(--text-2)">Order ✓　Stock 1 → 0</div></div><div style="border:1px solid var(--border);border-radius:8px;padding:12px;background:var(--bg);flex:1;min-width:190px"><b>Request B</b><div style="margin-top:8px;color:var(--text-2)">Order ✕　Stock remains 0</div></div></div><div style="text-align:center;margin-top:12px;color:var(--brand);font-weight:600">Final: one group succeeds, the other fails as a whole</div></div>'
