    demo: '<div class="testing-delivery-preview tdv-audit-log"><div class="tdv-table"><header><span>Time</span><span>Actor / action</span><span>Result</span></header><p><span>10:42</span><span>admin-lee \xb7 edit billing role</span><em>Denied</em></p><small>Target: role/billing-editor \xb7 Source: admin console</small></div></div>'
