  demo: '<div class="record-preview"><div class="hash-evidence"><div class="hash-file"><span>脚本内容 → 哈希前缀</span><pre>const message = &quot;Hello&quot;;</pre><strong>→ d3cc7661</strong><pre>const message = &quot;Hello!&quot;;</pre><strong>→ f8a8cd8b</strong></div></div></div>',
