  desc: "JavaScript 抛出异常时，调用栈通常先列离抛错点最近的函数，再列它的调用者。先在顶部附近找属于自己文件的帧，再结合代码和数据检查原因；栈给出位置线索，不单独证明根因。",
  demo: '<div class="wf-card wf-stack-card"><div class="wf-stack-mini"><div class="wf-stack-mini-head"><b>node save.js</b><code>TypeError</code></div><div class="wf-stack-mini-lines"><span>at loadRows <i>(save.js:24:21)</i></span><span>at handleSave <i>(save.js:5:20)</i></span><span class="muted">at processTicks… <i>(node:internal)</i></span></div></div><small>在栈里找到属于自己文件的那一帧</small></div>',
