  desc: "点击保存后页面等待到上限并报告超时，不等于服务端已停止处理或数据肯定没写入。本页例子假设请求已抵达服务端；其他超时也可能发生在连接、发送或读取阶段。重试前先确认这次操作的服务端结果，避免重复提交。",
