  tagline: "项目声明会使用的外部代码包，通常由包管理器按清单安装",
  desc: "克隆项目后，package.json 记录项目声明的依赖，锁文件记录解析出的具体版本；包管理器据此准备本地安装目录。源码仓库通常不提交 node_modules。遇到 Cannot find module 可以先看依赖是否安装，再按项目提示启动并核对实际报错。",
