  cn: "语义化版本",
  cat: "开发工具",
  tagline: "用主版本、次版本和修订号表达公开 API 兼容承诺的版本规则",
  desc: "SemVer 用 X.Y.Z 表达对公开 API 兼容性的承诺：稳定版本中，修订号表示兼容修复，次版本表示兼容新增，主版本表示不兼容变化。版本号是项目作者对 API 的约定，不是应用升级风险分数；0.y.z 版本尚未承诺稳定 API。",
  demo: '<div class="wf-card wf-semver-card"><div class="wf-semver-mini"><div class="wf-semver-mini-head"><b>package.json \xb7 示例</b><code>"sample-lib": "^1.2.3"</code></div><div class="wf-semver-mini-num"><span>1</span><i>.</i><span>2</span><i>.</i><span>3</span></div><small>主版本 . 次版本 . 修订号</small></div></div>',
  en: {
    quote: "AI says a dependency is moving from major version 1 to 2. Should I just upgrade?",
    tagline: "A versioning rule that uses major, minor, and patch to express a public API compatibility promise",
    desc: "SemVer uses X.Y.Z to express a promise about public API compatibility: for stable versions, patch means a compatible fix, minor means a compatible addition, and major means an incompatible change. A version is the author’s API contract, not an application upgrade risk score; 0.y.z versions have not promised a stable API.",
    demo: '<div class="wf-card wf-semver-card"><div class="wf-semver-mini"><div class="wf-semver-mini-head"><b>package.json \xb7 example</b><code>"sample-lib": "^1.2.3"</code></div><div class="wf-semver-mini-num"><span>1</span><i>.</i><span>2</span><i>.</i><span>3</span></div><small>major . minor . patch</small></div></div>'
  },
  quote: "AI 建议我把依赖从主版本 1 升到 2，我该直接升级吗？",
  aliases: ["语义化版本号", "SemVer"],
