  id: "rag",
  name: "RAG",
  cn: "RAG",
  cat: "AI 基础",
  tagline: "回答时先从指定资料中检索相关片段，再把它们交给模型参考的做法",
  desc: "客服回答退款问题时，RAG 会先从接入的政策资料中找相关段落，再让模型据此作答。新资料要完成处理并进入检索范围后，后续回答才有机会用到；检索仍可能漏掉内容或被模型误读。",
  demo: '\n  <div class="ai-card-visual ai-card-rag">\n    <div class="aic-rag-question"><small>顾客问题 \xb7 教学示例</small><b>我定制的杯子可以退吗？</b></div>\n    <div class="aic-rag-flow"><span class="aic-rag-source"><b>检索命中 \xb7 退款政策第 3 条</b><i>所有商品可在 7 天内申请退货</i></span><i>→</i><span class="aic-rag-answer"><b>客服答复</b><i>可在 7 天内申请退货。引自第 3 条。</i></span></div>\n    <div class="aic-foot">资料处理完成后，核对命中段落是否支持答复</div>\n  </div>',
  en: {
    quote: "I updated the refund policy. Why is AI still citing the old rule?",
    tagline: "A method that retrieves relevant passages from specified material at answer time and gives them to the model",
    desc: "When customer support answers a refund question, RAG first finds relevant passages in connected policy material and then lets the model answer from them. New material must finish processing and enter the searchable set before later answers can use it; retrieval may still miss a passage or the model may misread it.",
    demo: '\n  <div class="ai-card-visual ai-card-rag">\n    <div class="aic-rag-question"><small>Customer question \xb7 teaching example</small><b>Can I return my custom mug?</b></div>\n    <div class="aic-rag-flow"><span class="aic-rag-source"><b>Retrieved \xb7 Refund Policy, Section 3</b><i>All items may be returned within 7 days</i></span><i>→</i><span class="aic-rag-answer"><b>Support reply</b><i>You may request a return within 7 days. Source: Section 3.</i></span></div>\n    <div class="aic-foot">After processing completes, check that the passage supports the reply</div>\n  </div>'
  },
  quote: "我改了退款政策，为什么 AI 还在引用旧规则？",
