    demo: '\n  <div class="ai-card-visual ai-card-object-storage">\n    <div class="aic-os-split">\n      <span class="aic-os-file"><b>cover.png</b><i>File → object storage</i></span>\n      <span class="aic-os-db"><b>Title, address</b><i>Text → database</i></span>\n    </div>\n    <div class="aic-foot">Files and structured data are stored separately</div>\n  </div>'
