  desc: "在 Network 面板里，GET /api/articles/7 与 POST /api/articles 是两条不同请求。GET 表示安全读取；POST 把请求交给目标资源处理，具体是否创建或保存要看接口约定。方法说明请求语义，不保证选错时一定返回 405。",
  demo: '\n  <div class="ai-card-visual ai-card-methods">\n    <div class="aic-method-rows">\n      <span class="get">GET <i>读取</i></span>\n      <span class="post">POST <i>新建</i></span>\n      <span class="put">PUT <i>修改</i></span>\n      <span class="delete">DELETE <i>删除</i></span>\n    </div>\n    <div class="aic-foot">GET 用于安全读取；其他方法按接口约定理解</div>\n  </div>',
