    demo: '\n  <div class="ai-card-visual ai-card-methods">\n    <div class="aic-method-rows">\n      <span class="get">GET <i>Read</i></span>\n      <span class="post">POST <i>Create</i></span>\n      <span class="put">PUT <i>Update</i></span>\n      <span class="delete">DELETE <i>Delete</i></span>\n    </div>\n    <div class="aic-foot">GET reads; other methods follow the API contract</div>\n  </div>'
