  demo: '<div class="record-preview"><header class="record-header"><strong>pages/book/index.wxml</strong><span class="record-status">教学案例</span></header><div class="record-content mp-workbench"><section class="mp-source"><h3>index.wxml（节选）</h3><pre>&lt;view&gt;\n  &lt;text&gt;{{title}}&lt;/text&gt;\n  &lt;button&gt;预约这个时段&lt;/button&gt;\n&lt;/view&gt;</pre></section><div class="mp-binding"><code>title: &quot;周末陶艺体验&quot;</code><div class="mp-device"><header class="mp-host"><span>微信</span><span aria-hidden="true">\xb7\xb7\xb7　⊙</span></header><div class="mp-app"><span class="mp-app-name">青禾工作坊</span><h3>周末陶艺体验</h3><p>周六 14:00 \xb7 陶艺体验</p><div class="mp-time">14:00 — 15:30</div><span class="mp-submit styled">预约这个时段</span></div></div></div></div></div>',
